// Surface failed runs visibly: log full context so nothing fails silently.
const err = $json;
console.error('LENDLOOP WORKFLOW ERROR', JSON.stringify({
  workflow: err.workflow?.name,
  executionId: err.execution?.id,
  node: err.execution?.lastNodeExecuted,
  message: err.execution?.error?.message
}));
return [{ json: { logged: true, at: new Date().toISOString() } }];
